/* ---- src/melee/it/kinds/ithitodeman.c */
f32 it_802D48B0(f32* value, f32 target, f32 max_val, f32 accel, f32 decel)
{
    f32 current = *value;
    f32 diff = target - current;

    if (ABS(diff) > ABS(accel)) {
        if (diff > 0.0f) {
            target = current + accel;
        } else {
            target = current - accel;
        }
    } else if (ABS(diff) < ABS(decel)) {
        if (diff > 0.0f) {
            target = current + decel;
        } else {
            target = current - decel;
        }
    }

    if (target > 0.0f) {
        if (target > max_val) {
            target = max_val;
        }
    } else {
        if (target < -max_val) {
            target = -max_val;
        }
    }

    *value = target;
    return target;
}

